fn glob_match(text: &str, pattern: &str) -> bool {
    // Split the pattern on '*'. The segments between stars must appear in order.
    let segments: Vec<&str> = pattern.split('*').collect();
    // Fast paths:
    if segments.len() == 1 {
        return text == segments[0];
    }
    // First segment must match at start.
    let first = segments[0];
    if !first.is_empty() && !text.starts_with(first) {
        return false;
    }
    // Last segment must match at end.
    let last = segments[segments.len() - 1];
    if !last.is_empty() && !text.ends_with(last) {
        return false;
    }
    // Middle segments must appear in order in the remaining slice.
    let mut search_from = first.len();  // after the prefix
    let end_bound = text.len() - last.len(); // before the suffix
    for seg in &segments[1..segments.len() - 1] {
        if seg.is_empty() {
            continue;
        }
        let Some(pos) = text[search_from..end_bound].find(seg) else {
            return false;
        };
        search_from += pos + seg.len();
        if search_from > end_bound {
            return false;
        }
    }
    true
}
