Now the directive parsing:

```rust
pub fn parse(source: &str) -> Suppressions {
    let mut all_lines = HashSet::new();
    let mut rule_lines: HashMap<usize, Vec<String>> = HashMap::new();

    for (idx, line) in source.lines().enumerate() {
        let line_number = idx + 1;
        let mut search_from = 0;
        // find all %#ok<...> occurrences in this line
        while let Some(start) = line[search_from..].find("%#ok<") {
            let content_start = search_from + start + "%#ok<".len();
            // find closing '>'
            let Some(rel_end) = line[content_start..].find('>') else { break; };
            let content_end = content_start + rel_end;
            let content = line[content_start..content_end].trim();
            if is_all_directive(content) {
                all_lines.insert(line_number);
            } else if !content.is_empty() {
                rule_lines.entry(line_number).or_default().push(content.to_string());
            }
            search_from = content_end + 1;
        }
    }

    Suppressions { all_lines, rule_lines }
}
```

